      // Only a label style has this edit path: the core refuses every other key.
      for (const key of Object.keys(values)) {
        if (!isLabelStyleKey(key)) {
          throw { kind: "edit", message: `\`${key}\` is not a label style an edit may change` };
        }
      }
      const settings = (doc.view.settings ??= {});
      // A command that writes no different value changes nothing and adds no undo step, as the core does.
      const changed = Object.entries(values).some(([key, value]) =>
        value === null ? settings[key] !== undefined : settings[key] !== value,
      );
      if (!changed) {
        return { view: withHistory(doc), regions: entries(doc), created: null, label: "Label styles", calc_needed: false };
      }
      record(doc, "Label styles");
      for (const [key, value] of Object.entries(values)) {
        if (value === null) delete settings[key];
        else settings[key] = value;
      }
