      const targets = regionIds.map((regionId) => {
        const region = doc.view.regions.find((r) => r.id === regionId);
        if (!region) throw { kind: "region", message: `there is no region \`${regionId}\`` };
        return region;
      });
      const label = enabled ? "Enable region" : "Disable region";
      record(doc, label);
      for (const region of targets) region.enabled = enabled;
      return finish(doc, label);
